(()=>{'use strict';
const UPDATE_API='/api/updates',ANALYTICS_API='/api/franklin-analytics',VISITS_API='/api/visits',TOKEN_KEY='gtav-admin-token-v2';
const $=id=>document.getElementById(id);let token='',updates=[],analytics={summary:{},trend:[],sessions:[],topics:[],pages:[],devices:[],chats:[]},refreshTimer=0,activeChatSession='';
const fmt=n=>new Intl.NumberFormat().format(Number(n||0));const short=id=>String(id||'').slice(0,8);const when=v=>{if(!v)return'—';const d=new Date(String(v).replace(' ','T')+'Z');return Number.isNaN(d.getTime())?v:new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)};
function headers(){return{'Content-Type':'application/json','X-Admin-Token':token,'Accept':'application/json'}}
async function req(url,options={}){const r=await fetch(url,{cache:'no-store',...options});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'request_failed');return d}
function setSync(text){$('sync-label').textContent=text}
function releaseStatus(text,kind=''){$('release-status').textContent=text;$('release-status').className='form-status'+(kind?' '+kind:'')}
async function unlock(candidate){token=String(candidate||'').trim();if(!token)return;$('login-status').textContent='Checking access…';try{await req(UPDATE_API+'?admin=1',{headers:headers()});await req(ANALYTICS_API,{headers:headers()});sessionStorage.setItem(TOKEN_KEY,token);$('lock').hidden=true;$('dashboard').hidden=false;$('login-status').textContent='Access granted.';await refreshAll();clearInterval(refreshTimer);refreshTimer=setInterval(refreshAll,60000)}catch(e){token='';sessionStorage.removeItem(TOKEN_KEY);$('login-status').textContent=e.message==='unauthorized'?'Invalid admin token.':'Admin API is unavailable.'}}
async function refreshAll(){setSync('Refreshing…');try{const [u,a,v]=await Promise.all([req(UPDATE_API+'?admin=1',{headers:headers()}),req(ANALYTICS_API,{headers:headers()}),req(VISITS_API).catch(()=>({visits:0}))]);updates=Array.isArray(u.updates)?u.updates:[];analytics=a||analytics;renderOverview(v.visits||0);renderSessions();renderReleases();if(activeChatSession)renderChat(activeChatSession);setSync('Synced '+new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit'}).format(new Date()))}catch(e){setSync('Sync error')}}
function renderOverview(visits){const s=analytics.summary||{};$('m-users').textContent=fmt(s.uniqueUsers);$('m-users-today').textContent=fmt(s.usersToday)+' today';$('m-sessions').textContent=fmt(s.sessions);$('m-questions').textContent=fmt(s.questions);$('m-questions-today').textContent=fmt(s.questionsToday)+' today';$('m-opens').textContent=fmt(s.opens);$('m-visits').textContent=fmt(visits);$('m-releases').textContent=fmt(updates.filter(x=>x.published).length);$('m-drafts').textContent=fmt(updates.filter(x=>!x.published).length)+' drafts';renderRanks('topic-list',analytics.topics||[],'topic','count');renderRanks('page-list',analytics.pages||[],'page','questions');drawTrend();drawDevices()}
function renderRanks(id,rows,labelKey,valueKey){const root=$(id);root.replaceChildren();if(!rows.length){root.innerHTML='<div class="empty">No data yet.</div>';return}const max=Math.max(...rows.map(r=>Number(r[valueKey]||0)),1);rows.forEach(r=>{const item=document.createElement('div'),label=document.createElement('div'),track=document.createElement('div'),fill=document.createElement('div');item.className='rank-item';label.className='rank-label';track.className='rank-track';fill.className='rank-fill';const a=document.createElement('span'),b=document.createElement('span');a.textContent=r[labelKey]||'unknown';b.textContent=fmt(r[valueKey]);label.append(a,b);fill.style.width=(Number(r[valueKey]||0)/max*100)+'%';track.append(fill);item.append(label,track);root.append(item)})}
function prepCanvas(canvas){const rect=canvas.getBoundingClientRect(),dpr=Math.max(1,devicePixelRatio||1);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return{ctx,w:rect.width,h:rect.height}}
function chartText(){return getComputedStyle(document.documentElement).dataset?.mode==='light'?'#555':'#bbb'}
function drawTrend(){const canvas=$('trend-chart'),rows=analytics.trend||[];if(!canvas||!rows.length)return;const{ctx,w,h}=prepCanvas(canvas),pad={l:34,r:12,t:18,b:30},cw=w-pad.l-pad.r,ch=h-pad.t-pad.b,max=Math.max(1,...rows.flatMap(r=>[Number(r.questions||0),Number(r.users||0)]));ctx.clearRect(0,0,w,h);ctx.font='11px system-ui';ctx.fillStyle=chartText();ctx.strokeStyle='rgba(150,150,150,.18)';for(let i=0;i<=4;i++){const y=pad.t+ch*i/4;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillText(Math.round(max*(1-i/4)),4,y+4)}const accent=getComputedStyle(document.documentElement).getPropertyValue('--site-accent').trim()||'#ffb511';const plot=(key,color,width)=>{ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();rows.forEach((r,i)=>{const x=pad.l+(rows.length===1?0:cw*i/(rows.length-1)),y=pad.t+ch-(Number(r[key]||0)/max)*ch;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()};plot('questions',accent,2.5);plot('users','#8798ff',1.8);ctx.fillStyle=chartText();[0,Math.floor((rows.length-1)/2),rows.length-1].forEach(i=>{const x=pad.l+(rows.length===1?0:cw*i/(rows.length-1));ctx.fillText(rows[i].date.slice(5),x-13,h-8)})}
function drawDevices(){const canvas=$('device-chart'),rows=analytics.devices||[];if(!canvas)return;const{ctx,w,h}=prepCanvas(canvas);ctx.clearRect(0,0,w,h);if(!rows.length){ctx.fillStyle=chartText();ctx.font='13px system-ui';ctx.fillText('No device data yet.',18,30);return}const max=Math.max(1,...rows.map(r=>Number(r.users||0))),bh=Math.min(38,(h-30)/rows.length),accent=getComputedStyle(document.documentElement).getPropertyValue('--site-accent').trim()||'#ffb511';ctx.font='12px system-ui';rows.forEach((r,i)=>{const y=16+i*bh,barW=(w-125)*Number(r.users||0)/max;ctx.fillStyle='rgba(140,140,140,.14)';ctx.fillRect(86,y,w-110,12);ctx.fillStyle=accent;ctx.fillRect(86,y,barW,12);ctx.fillStyle=chartText();ctx.fillText(r.device,8,y+10);ctx.fillText(fmt(r.users),w-20,y+10)})}
function chatCount(sessionId){return(analytics.chats||[]).filter(m=>m.session_id===sessionId).length}
function renderSessions(){const q=$('session-search').value.trim().toLowerCase(),rows=(analytics.sessions||[]).filter(r=>!q||[r.user_id,r.session_id,r.page,r.device_type,r.language].some(v=>String(v||'').toLowerCase().includes(q)));$('session-count').textContent=rows.length+' SESSIONS';const body=$('sessions-body');body.replaceChildren();if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=9;td.className='empty';td.textContent='No matching sessions yet.';tr.append(td);body.append(tr);return}rows.forEach(r=>{const tr=document.createElement('tr');[short(r.user_id),short(r.session_id),r.page||'—',r.device_type||'—',r.language||'—',fmt(r.questions),when(r.started_at),when(r.last_active)].forEach((v,i)=>{const td=document.createElement('td');td.textContent=v;if(i<2)td.style.fontFamily='ui-monospace,SFMono-Regular,Menlo,monospace';tr.append(td)});const td=document.createElement('td'),button=document.createElement('button'),count=chatCount(r.session_id);button.className='mini view-chat';button.type='button';button.textContent=count?`View chat (${count})`:'No chat';button.disabled=!count;button.onclick=()=>renderChat(r.session_id);td.append(button);tr.append(td);body.append(tr)})}
function renderChat(sessionId){activeChatSession=sessionId;const card=$('chat-card'),thread=$('chat-thread'),title=$('chat-title'),meta=$('chat-subtitle'),messages=(analytics.chats||[]).filter(m=>m.session_id===sessionId);card.hidden=false;thread.replaceChildren();title.textContent='Conversation · '+short(sessionId);meta.textContent=`${messages.length} messages · retained up to ${analytics.chatRetentionHours||24} hours`;if(!messages.length){thread.innerHTML='<div class="empty">This session has no retained chat content.</div>';return}messages.forEach(m=>{const bubble=document.createElement('div');bubble.className='chat-message '+(m.role==='user'?'user':'franklin');const text=document.createElement('div');text.textContent=m.content;const foot=document.createElement('div');foot.className='chat-meta';const who=document.createElement('span');who.textContent=m.role==='user'?'User':'Franklin';const time=document.createElement('span');time.textContent=when(m.created_at);const topic=document.createElement('span');topic.textContent=m.topic||'other';foot.append(who,time,topic);bubble.append(text,foot);thread.append(bubble)});requestAnimationFrame(()=>{card.scrollIntoView({behavior:'smooth',block:'start'});thread.scrollTop=thread.scrollHeight})}
function payload(){return{title:$('title').value,releaseDate:$('release-date').value,category:$('category').value,version:$('version').value,summary:$('summary').value,body:$('body').value,downloadUrl:$('download-url').value,imageUrl:$('image-url').value,published:$('published').checked}}
function resetForm(){$('release-form').reset();$('editing-id').value='';$('release-date').value=new Date().toISOString().slice(0,10);$('published').checked=true;$('form-title').textContent='New update';$('save-release').textContent='Publish update';$('cancel-edit').hidden=true;releaseStatus('')}
function renderReleases(){const root=$('release-list');root.replaceChildren();$('release-count').textContent=updates.length+' ITEMS';if(!updates.length){root.innerHTML='<div class="empty">No dashboard releases yet.</div>';return}updates.forEach((item,index)=>{const card=document.createElement('article');card.className='release-item';const top=document.createElement('div');top.className='release-top';if(index===0&&item.published){const b=document.createElement('span');b.className='new-badge';b.textContent='NEW';top.append(b)}if(!item.published){const b=document.createElement('span');b.className='draft-badge';b.textContent='DRAFT';top.append(b)}const tag=document.createElement('span');tag.className='pill';tag.textContent=item.category||'Update';top.append(tag);const time=document.createElement('time');time.textContent=item.releaseDate||'';top.append(time);const h=document.createElement('h3');h.textContent=item.title;const p=document.createElement('p');p.textContent=item.summary||item.version||'No summary';const actions=document.createElement('div');actions.className='release-actions';const edit=document.createElement('button');edit.className='mini';edit.textContent='Edit';edit.onclick=()=>editRelease(item.id);const del=document.createElement('button');del.className='mini danger';del.textContent='Delete';del.onclick=()=>deleteRelease(item.id);actions.append(edit,del);card.append(top,h,p,actions);root.append(card)})}
function editRelease(id){const x=updates.find(u=>u.id===id);if(!x)return;$('editing-id').value=x.id;$('title').value=x.title||'';$('release-date').value=x.releaseDate||'';$('category').value=x.category||'Update';$('version').value=x.version||'';$('summary').value=x.summary||'';$('body').value=x.body||'';$('download-url').value=x.downloadUrl||'';$('image-url').value=x.imageUrl||'';$('published').checked=!!x.published;$('form-title').textContent='Edit update';$('save-release').textContent='Save changes';$('cancel-edit').hidden=false;releaseStatus('Editing selected release.');activateTab('releases');scrollTo({top:0,behavior:'smooth'})}
async function deleteRelease(id){if(!confirm('Delete this update permanently?'))return;try{await req(UPDATE_API+'?id='+encodeURIComponent(id),{method:'DELETE',headers:headers()});await refreshAll();if($('editing-id').value===id)resetForm()}catch(e){releaseStatus('Delete failed: '+e.message,'error')}}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},0)}
function exportCsv(){const rows=[['user_id','session_id','page','device','language','questions','started_at','last_active'],...(analytics.sessions||[]).map(r=>[r.user_id,r.session_id,r.page,r.device_type,r.language,r.questions,r.started_at,r.last_active])];download('franklin-usage.csv',rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv')}
function activateTab(name){document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===name));document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('active',p.id==='panel-'+name));requestAnimationFrame(()=>{if(name==='overview'){drawTrend();drawDevices()}})}
document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>activateTab(t.dataset.tab)));$('login-form').addEventListener('submit',e=>{e.preventDefault();unlock($('token').value)});$('lock-out').onclick=()=>{clearInterval(refreshTimer);sessionStorage.removeItem(TOKEN_KEY);token='';$('dashboard').hidden=true;$('lock').hidden=false;$('token').value='';$('token').focus()};$('refresh-all').onclick=refreshAll;$('session-search').addEventListener('input',renderSessions);$('export-json').onclick=()=>download('franklin-analytics.json',JSON.stringify(analytics,null,2));$('export-csv').onclick=exportCsv;$('cancel-edit').onclick=resetForm;$('close-chat').onclick=()=>{$('chat-card').hidden=true;activeChatSession=''};$('release-date').value=new Date().toISOString().slice(0,10);
$('release-form').addEventListener('submit',async e=>{e.preventDefault();const id=$('editing-id').value;releaseStatus(id?'Saving…':'Publishing…');$('save-release').disabled=true;try{await req(UPDATE_API+(id?'?id='+encodeURIComponent(id):''),{method:id?'PUT':'POST',headers:headers(),body:JSON.stringify(payload())});await refreshAll();resetForm();releaseStatus(id?'Changes saved.':'Update published.','ok')}catch(err){releaseStatus('Could not save: '+err.message,'error')}finally{$('save-release').disabled=false}});
addEventListener('resize',()=>{clearTimeout(window.__dashResize);window.__dashResize=setTimeout(()=>{if($('panel-overview').classList.contains('active')){drawTrend();drawDevices()}},120)});
const saved=sessionStorage.getItem(TOKEN_KEY);if(saved)unlock(saved);
})();